-- Masha Store schema proposal for a NEW SQLite / Cloudflare D1 database only.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,name_ar TEXT NOT NULL,description_ar TEXT NOT NULL DEFAULT '',category TEXT NOT NULL CHECK(category IN ('girls','boys','baby','sets')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,sku TEXT UNIQUE,size_label TEXT NOT NULL,color_name TEXT NOT NULL DEFAULT '',color_hex TEXT,price_iqd INTEGER NOT NULL CHECK(price_iqd>=0),compare_at_iqd INTEGER CHECK(compare_at_iqd IS NULL OR compare_at_iqd>=price_iqd),stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),UNIQUE(product_id,size_label,color_name));
CREATE TABLE IF NOT EXISTS product_media(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,media_type TEXT NOT NULL CHECK(media_type IN ('image','instagram_embed','video_file')),url TEXT NOT NULL,alt_ar TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)));
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone_normalized TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customers_phone ON customers(phone_normalized);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,customer_id TEXT REFERENCES customers(id),customer_name TEXT NOT NULL,phone_normalized TEXT NOT NULL,governorate TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'received' CHECK(status IN ('received','confirmed','preparing','shipped','delivered','cancelled','returned')),subtotal_iqd INTEGER NOT NULL CHECK(subtotal_iqd>=0),delivery_fee_iqd INTEGER NOT NULL DEFAULT 0 CHECK(delivery_fee_iqd>=0),total_iqd INTEGER NOT NULL CHECK(total_iqd=subtotal_iqd+delivery_fee_iqd),idempotency_key TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_status_created ON orders(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_phone_created ON orders(phone_normalized,created_at DESC);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,variant_id TEXT REFERENCES product_variants(id),product_name_snapshot TEXT NOT NULL,size_snapshot TEXT NOT NULL,color_snapshot TEXT NOT NULL DEFAULT '',unit_price_iqd INTEGER NOT NULL CHECK(unit_price_iqd>=0),quantity INTEGER NOT NULL CHECK(quantity>0),line_total_iqd INTEGER NOT NULL CHECK(line_total_iqd=unit_price_iqd*quantity));
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
-- Validate prices and decrement inventory in a server-side transaction. Never trust client totals.
